pub fn getSpecifierSpecificity(spec: []const u8) u8 {
        if ((spec.len == 0)) {
            return 9;
        }
        if ((spec[0] == 42)) {
            return 1;
        }
        if (strings.indexOf(spec, ".x")) |_| {
            return 5;
        }
        if (strings.indexOfAny(spec, "<>=")) |_| {
            return 6;
        }
        if ((spec[0] == 126)) {
            return 7;
        }
        if ((spec[0] == 94)) {
            return 8;
        }
        if (strings.indexOf(spec, "workspace:")) |_| {
            return 9;
        }
        if (std.ascii.isDigit(spec[0])) {
            return 10;
        }
        return 3;
}

pub fn getDependencyTypePriority(dep_type: DependencyType) u8 {
        return (switch (dep_type) {
.prod => 4,
.peer => 3,
.optional_peer => 2,
.optional => 1,
.dev => 0,
});
}

pub fn compareDependents(context: void, a: DependentInfo, b: DependentInfo) bool {
        _ = &context;
        const a_specificity = getSpecifierSpecificity(a.spec);
        const b_specificity = getSpecifierSpecificity(b.spec);
        if ((a_specificity != b_specificity)) {
            return (a_specificity > b_specificity);
        }
        const a_type_priority = getDependencyTypePriority(a.dep_type);
        const b_type_priority = getDependencyTypePriority(b.dep_type);
        if ((a_type_priority != b_type_priority)) {
            return (a_type_priority > b_type_priority);
        }
        return std.mem.lessThan(u8, a.name, b.name);
}

pub fn printUsage() void {
        _ = Output.prettyln((("<r><b>bun why<r> <d>v" ++ Global.package_json_version_with_sha) ++ "<r>"), .{});
        const usage_text: []const u8 = "Explain why a package is installed";
        _ = "";
        _ = "<b>Arguments:<r>";
        _ = "  <blue>\\<package\\><r>     <d>The package name to explain (supports glob patterns like '@org/*')<r>";
        _ = "";
        _ = "<b>Options:<r>";
        _ = "  <cyan>--top<r>         <d>Show only the top dependency tree instead of nested ones<r>";
        _ = "  <cyan>--depth<r> <blue>\\<NUM\\><r> <d>Maximum depth of the dependency tree to display<r>";
        _ = "";
        _ = "<b>Examples:<r>";
        _ = "  <d>$<r> <b><green>bun why<r> <blue>react<r>";
        _ = "  <d>$<r> <b><green>bun why<r> <blue>\"@types/*\"<r> <cyan>--depth<r> <blue>2<r>";
        _ = "  <d>$<r> <b><green>bun why<r> <blue>\"*-lodash\"<r> <cyan>--top<r>";
        _ = "";
        _ = Output.pretty(usage_text, .{});
        _ = Output.flush();
}

pub fn execInternal(ctx: Command.Context) !void {
        const cli = try PackageManager.CommandLineArguments.parse(ctx.allocator, .why);
        const init_res = try PackageManager.init(ctx, cli, PackageManager.Subcommand.why);
        var pm = init_res[0];
        _ = &pm;
        if ((cli.positionals.len < 1)) {
            _ = printUsage();
            _ = Global.exit(1);
        }
        if (strings.eqlComptime(cli.positionals[0], "why")) {
            if ((cli.positionals.len < 2)) {
                _ = printUsage();
                _ = Global.exit(1);
            }
            return try execWithManager(ctx, pm, cli.positionals[1], cli.top_only);
        }
        return try execWithManager(ctx, pm, cli.positionals[0], cli.top_only);
}

pub fn execFromPmInternal(ctx: Command.Context, pm: *PackageManager, positionals: []const []const u8) !void {
        if ((positionals.len < 2)) {
            _ = printUsage();
            _ = Global.exit(1);
        }
        _ = try execWithManager(ctx, pm, positionals[1], pm.options.top_only);
}

pub fn execWithManager(ctx: Command.Context, pm: *PackageManager, package_pattern: []const u8, top_only: bool) !void {
        const load_lockfile = pm.lockfile.loadFromCwd(pm, ctx.allocator, ctx.log, true);
        _ = PackageManagerCommand.handleLoadLockfileErrors(load_lockfile, pm);
        if (top_only) {
            max_depth = 1;
        } else {
            if (pm.options.depth) |depth| {
                _ = &depth;
                max_depth = depth;
            } else {
                max_depth = 100;
            }
        }
        const lockfile = load_lockfile.ok.lockfile;
        const string_bytes = lockfile.buffers.string_bytes.items;
        const packages = lockfile.packages.slice();
        const dependencies_items = lockfile.buffers.dependencies.items;
        const resolutions_items = lockfile.buffers.resolutions.items;
        var arena_ = std.heap.ArenaAllocator.init(ctx.allocator);
        _ = &arena_;
        defer {
        _ = arena_.deinit();
        }
        const arena_allocator = arena_.allocator();
        var target_versions = std.array_list.Managed(VersionInfo).init(ctx.allocator);
        _ = &target_versions;
        defer {
        {
            for (target_versions.items) |item| {
                _ = &item;
                _ = ctx.allocator.free(item.version);
            }
            _ = target_versions.deinit();
        }
        }
        var all_dependents = std.AutoHashMap(PackageID, std.array_list.Managed(DependentInfo)).init(arena_allocator);
        _ = &all_dependents;
        const glob = GlobPattern.init(package_pattern);
        var pkg_idx: usize = 0;
        _ = &pkg_idx;
        while ((pkg_idx < packages.len)) : (pkg_idx = (pkg_idx + 1)) {
            const pkg = packages.get(pkg_idx);
            const pkg_name = (if (@typeInfo(@TypeOf(pkg)) == .@"enum" or @typeInfo(@TypeOf(pkg)) == .@"union") @tagName(pkg) else pkg.name).slice(string_bytes);
            if ((pkg_name.len == 0)) {
                continue;
            }
            const dependencies = pkg.dependencies.get(dependencies_items);
            const resolutions = pkg.resolutions.get(resolutions_items);
            var dep_idx: usize = 0;
            _ = &dep_idx;
            for (cp_iter_slice(dependencies)) |dependency| {
                _ = &dependency;
                const target_id = resolutions[@as(usize, @intCast(dep_idx))];
                dep_idx = (dep_idx + 1);
                if ((target_id >= packages.len)) {
                    continue;
                }
                var dependents_entry = try all_dependents.getOrPut(target_id);
                _ = &dependents_entry;
                if ((!dependents_entry.found_existing)) {
                    dependents_entry.value_ptr.* = std.array_list.Managed(DependentInfo).init(arena_allocator);
                }
                var dep_version_buf = std.array_list.Managed(u8).init(arena_allocator);
                _ = &dep_version_buf;
                defer {
                _ = dep_version_buf.deinit();
                }
                _ = try dep_version_buf.writer().print("{f}", .{ packages.items(.resolution)[@as(usize, @intCast(pkg_idx))].fmt(string_bytes, .auto) });
                const dep_pkg_version = try arena_allocator.dupe(u8, dep_version_buf.items);
                const spec = try arena_allocator.dupe(u8, dependency.version.literal.slice(string_bytes));
                const dep_type = (if (dependency.behavior.dev) DependencyType.dev else (if ((dependency.behavior.optional and dependency.behavior.peer)) DependencyType.optional_peer else (if (dependency.behavior.optional) DependencyType.optional else (if (dependency.behavior.peer) DependencyType.peer else DependencyType.prod))));
                _ = try dependents_entry.value_ptr.append(.{ .name = try arena_allocator.dupe(u8, pkg_name), .version = dep_pkg_version, .spec = spec, .dep_type = dep_type, .pkg_id = @as(PackageID, @intCast(pkg_idx)), .workspace = (strings.hasPrefixComptime(dep_pkg_version, "workspace:") or (dep_pkg_version.len == 0)) });
            }
            if ((!glob.matchesName(pkg_name, package_pattern))) {
                continue;
            }
            var version_buf = std.array_list.Managed(u8).init(ctx.allocator);
            _ = &version_buf;
            defer {
            _ = version_buf.deinit();
            }
            _ = try version_buf.writer().print("{f}", .{ packages.items(.resolution)[@as(usize, @intCast(pkg_idx))].fmt(string_bytes, .auto) });
            const version = try ctx.allocator.dupe(u8, version_buf.items);
            if ((!glob.matchesVersion(version))) {
                continue;
            }
            _ = try target_versions.append(.{ .version = version, .pkg_id = @as(PackageID, @intCast(pkg_idx)) });
        }
        if ((target_versions.items.len == 0)) {
            _ = Output.prettyln("<r><red>error<r>: No packages matching '{s}' found in lockfile", .{ package_pattern });
            _ = Global.exit(1);
        }
        for (target_versions.items) |target_version| {
            _ = &target_version;
            const target_pkg = packages.get(target_version.pkg_id);
            const target_name = (if (@typeInfo(@TypeOf(target_pkg)) == .@"enum" or @typeInfo(@TypeOf(target_pkg)) == .@"union") @tagName(target_pkg) else target_pkg.name).slice(string_bytes);
            _ = Output.prettyln("<b>{s}@{s}<r>", .{ target_name, target_version.version });
            if (all_dependents.get(target_version.pkg_id)) |dependents| {
                _ = &dependents;
                if ((dependents.items.len == 0)) {
                    _ = Output.prettyln("<d>  └─ No dependents found<r>", .{});
                } else {
                    if ((max_depth == 0)) {
                        _ = Output.prettyln("<d>  └─ (deeper dependencies hidden)<r>", .{});
                    } else {
                        var ctx_data = TreeContext.init(arena_allocator, string_bytes, top_only, (&all_dependents));
                        _ = &ctx_data;
                        defer {
                        _ = ctx_data.clearPathTracker();
                        }
                        _ = std.sort.insertion(DependentInfo, dependents.items, .{}, compareDependents);
                        var dep_idx: usize = 0;
                        _ = &dep_idx;
                        for (dependents.items) |dep| {
                            _ = &dep;
                            const is_last = (dep_idx == (dependents.items.len - 1));
                            const prefix = (if (is_last) PREFIX_LAST else PREFIX_MIDDLE);
                            dep_idx = (dep_idx + 1);
                            _ = printPackageWithType(prefix, (&dep));
                            if ((!top_only)) {
                                _ = try printDependencyTree((&ctx_data), dep.pkg_id, (if (is_last) PREFIX_SPACE else PREFIX_CONTINUE), 1, is_last, dep.workspace);
                            }
                        }
                    }
                }
            } else {
                _ = Output.prettyln("<d>  └─ No dependents found<r>", .{});
            }
            _ = Output.prettyln("", .{});
            _ = Output.flush();
        }
}

pub fn printPackageWithType(prefix: []const u8, package: *const DependentInfo) void {
        _ = Output.pretty("<d>{s}<r>", .{ prefix });
        switch (package.dep_type) {
.dev => {
_ = Output.pretty("<magenta>dev<r> ", .{});
},
.peer => {
_ = Output.pretty("<yellow>peer<r> ", .{});
},
.optional => {
_ = Output.pretty("<cyan>optional<r> ", .{});
},
.optional_peer => {
_ = Output.pretty("<cyan>optional peer<r> ", .{});
},
else => {

},
}
        if (package.workspace) {
            _ = Output.pretty("<blue>{s}<r>", .{ package.name });
            if ((package.version.len > 0)) {
                _ = Output.pretty("<d><blue>@workspace<r>", .{});
            }
        } else {
            _ = Output.pretty("{s}", .{ package.name });
            if ((package.version.len > 0)) {
                _ = Output.pretty("<d>@{s}<r>", .{ package.version });
            }
        }
        if ((package.spec.len > 0)) {
            _ = Output.prettyln(" <d>(requires {s})<r>", .{ package.spec });
        } else {
            _ = Output.prettyln("", .{});
        }
}

pub fn printDependencyTree(ctx: *TreeContext, current_pkg_id: PackageID, prefix: []const u8, depth: usize, printed_break_line: bool, parent_is_workspace: bool) !void {
        if ((ctx.path_tracker.get(current_pkg_id) != null)) {
            _ = Output.prettyln("<d>{s}└─ <yellow>*circular<r>", .{ prefix });
            return;
        }
        _ = try ctx.path_tracker.put(current_pkg_id, depth);
        defer {
        _ = ctx.path_tracker.remove(current_pkg_id);
        }
        if (ctx.all_dependents.get(current_pkg_id)) |dependents| {
            _ = &dependents;
            const sorted_dependents = try ctx.allocator.dupe(DependentInfo, dependents.items);
            defer {
            _ = ctx.allocator.free(sorted_dependents);
            }
            _ = std.sort.insertion(DependentInfo, sorted_dependents, .{}, compareDependents);
            var dep_idx: usize = 0;
            _ = &dep_idx;
            for (cp_iter_slice(sorted_dependents)) |dep| {
                _ = &dep;
                if ((parent_is_workspace and (dep.version.len == 0))) {
                    dep_idx = (dep_idx + 1);
                    continue;
                }
                if ((depth >= max_depth)) {
                    _ = Output.prettyln("<d>{s}└─ (deeper dependencies hidden)<r>", .{ prefix });
                    return;
                }
                const is_dep_last = (dep_idx == (sorted_dependents.len - 1));
                const prefix_char = (if (is_dep_last) "└─ " else "├─ ");
                dep_idx = (dep_idx + 1);
                const full_prefix = try std.fmt.allocPrint(ctx.allocator, "{s}{s}", .{ prefix, prefix_char });
                _ = printPackageWithType(full_prefix, (&dep));
                const next_prefix = try std.fmt.allocPrint(ctx.allocator, "{s}{s}", .{ prefix, (if (is_dep_last) "   " else "│  ") });
                const print_break_line = ((is_dep_last and (sorted_dependents.len > 1)) and (!printed_break_line));
                _ = try printDependencyTree(ctx, dep.pkg_id, next_prefix, (depth + 1), (printed_break_line or print_break_line), dep.workspace);
                if (print_break_line) {
                    _ = Output.prettyln("<d>{s}<r>", .{ prefix });
                }
            }
        }
}
